"use client";
import { useRef, useState } from "react";
import { Expand, ExternalLink, ImageOff, X } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import type { HistoricalImage } from "@/data/types";
import imageSizeData from "@/data/image-sizes.json";

type ImageSizes = Record<
  string,
  { width: number; height: number; variants: { width: number; src: string }[] }
>;
// Generated by scripts/build-images.mjs alongside the WebP renditions.
const imageSizes = imageSizeData as ImageSizes;

/**
 * Renders an archival image at a size close to its display box.
 *
 * The JPEG in `localSrc` stays as the `<img>` source so the picture still works
 * if WebP or the derived files are unavailable; browsers that understand the
 * `<source>` pick a rendition sized for the layout instead of the full museum
 * download. `sizes` describes the drawn width, not the file width.
 */
export function ArtImage({
  image,
  className = "",
  eager = false,
  sizes = "(max-width: 767px) 100vw, 640px",
}: {
  image: HistoricalImage;
  className?: string;
  eager?: boolean;
  sizes?: string;
}) {
  const [failedSource, setFailedSource] = useState<string | null>(null);
  const meta = imageSizes[image.id];
  if (failedSource === image.localSrc)
    return (
      <span className={`image-missing ${className}`}>
        <ImageOff size={22} />
        图像暂不可用
      </span>
    );
  const picture = (
    <img
      className={className}
      src={image.localSrc}
      alt={image.alt}
      // Intrinsic dimensions reserve the right box before the bytes arrive, so
      // the surrounding text does not jump once an image loads.
      width={meta?.width}
      height={meta?.height}
      loading={eager ? "eager" : "lazy"}
      decoding="async"
      // Only the day cover is above the fold; everything else may wait.
      fetchPriority={eager ? "high" : undefined}
      onError={() => setFailedSource(image.localSrc)}
    />
  );
  if (!meta?.variants.length) return picture;
  return (
    <picture>
      <source
        type="image/webp"
        sizes={sizes}
        srcSet={meta.variants.map((v) => `${v.src} ${v.width}w`).join(", ")}
      />
      {picture}
    </picture>
  );
}
export function ImageCredit({ image }: { image: HistoricalImage }) {
  const licenseUrl = image.license.match(/https:\/\/[^\s；）]+/)?.[0];
  return (
    <div className="image-credit">
      <p>{image.credit}</p>
      <p>{image.license.split("（")[0]} · 展示缩略图可能裁切，原图未改动</p>
      <div>
        <a href={image.sourceUrl} target="_blank" rel="noreferrer">
          馆藏与图像来源 <ExternalLink size={12} />
        </a>
        {licenseUrl && (
          <a href={licenseUrl} target="_blank" rel="noreferrer">
            许可说明 <ExternalLink size={12} />
          </a>
        )}
      </div>
    </div>
  );
}
export default function HeritageImage({
  image,
  context = false,
  open,
  onOpenChange: setOpen,
}: {
  image: HistoricalImage;
  context?: boolean;
  open: boolean;
  onOpenChange: (value: boolean) => void;
}) {
  const trigger = useRef<HTMLButtonElement>(null);
  return (
    <>
      <figure className="heritage-figure">
        <button
          ref={trigger}
          className="heritage-image-button"
          onClick={() => setOpen(true)}
          aria-label={`放大图像：${image.title}`}
        >
          <ArtImage image={image} sizes="(max-width: 767px) 100vw, 420px" />
          <span>
            <Expand size={15} />
            查看全图
          </span>
        </button>
        <figcaption>
          <span className="figure-overline">
            {context ? "本时期图像参考" : "文物与图像"}
          </span>
          <strong>{image.title}</strong>
          <small>{image.dating}</small>
          <details>
            <summary>图像说明与授权</summary>
            <p>{image.caption}</p>
            <ImageCredit image={image} />
          </details>
        </figcaption>
      </figure>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent
          className="art-lightbox"
          showCloseButton={false}
          onEscapeKeyDown={(event) => {
            event.preventDefault();
            event.stopPropagation();
            setOpen(false);
          }}
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            trigger.current?.focus({ preventScroll: true });
          }}
        >
          <button
            className="lightbox-close panel-icon"
            onClick={() => setOpen(false)}
            aria-label="关闭全图"
          >
            <X size={20} />
          </button>
          <DialogTitle>{image.title}</DialogTitle>
          <DialogDescription>{image.dating}</DialogDescription>
          <div className="lightbox-scroll">
            <ArtImage image={image} eager sizes="90vw" />
            <p>{image.caption}</p>
            <ImageCredit image={image} />
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}
